const ALLOWED_DOMAINS = ['api.trusted-domain.com', 'another-trusted.com'];

app.post('/fetch-data', express.json(), (req, res) => {
  const { url } = req.body;

  if (!url || typeof url !== 'string') {
    return res.status(400).json({ error: 'Valid URL required' });
  }

  try {
    const parsedUrl = new URL(url);

    // Block private IPs
    if (isPrivateIP(parsedUrl.hostname)) {
      return res.status(403).json({ error: 'Access to private IPs not allowed' });
    }

    // Whitelist check
    if (!ALLOWED_DOMAINS.includes(parsedUrl.hostname)) {
      return res.status(403).json({ error: 'Domain not whitelisted' });
    }

    // Set timeout and size limits
    const response = await axios.get(url, {
      timeout: 5000,
      maxContentLength: 1024 * 1024, // 1MB max
      maxRedirects: 2,
    });

    res.json(response.data);
  } catch (error) {
    res.status(400).json({ error: 'Failed to fetch URL' });
  }
});

function isPrivateIP(hostname) {
  const privateRanges = [
    /^localhost$/,
    /^127\./,
    /^10\./,
    /^172\.(1[6-9]|2[0-9]|3[01])\./,
    /^192\.168\./,
    /^169\.254\./,
  ];
  return privateRanges.some(range => range.test(hostname));
}
