```javascript
// SECURE APPROACH: Use a secret management service

const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

// Load secrets from AWS Secrets Manager (production)
async function loadSecrets() {
  try {
    const secret = await secretsManager.getSecretValue({
      SecretId: process.env.SECRET_NAME || 'app/production/secrets'
    }).promise();

    const credentials = JSON.parse(secret.SecretString);
    return credentials;
  } catch (error) {
    console.error('Failed to load secrets:', error);
    throw new Error('Unable to load required secrets');
  }
}

// Validate all required environment variables at startup
function validateEnvironment() {
  const required = [
    'NODE_ENV',
    'PORT',
    'JWT_SECRET',
    'DATABASE_URL',
  ];

  for (const envVar of required) {
    if (!process.env[envVar]) {
      throw new Error(`Missing required environment variable: ${envVar}`);
    }
  }

  // Validate SECRET format (minimum length, complexity)
  if (process.env.JWT_SECRET.length < 32) {
    throw new Error('JWT_SECRET must be at least 32 characters');
  }
}

// Force HTTPS in production
const express = require('express');
const app = express();

app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(307, `https://${req.get('host')}${req.url}`);
  }
  next();
});

// Enforce HSTS headers
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production') {
    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  }
  next();
});

// Prevent credential exposure in error messages
app.use((err, req, res, next) => {
  // Never expose sensitive data in error responses
  const isDevelopment = process.env.NODE_ENV === 'development';

  const errorResponse = {
    error: 'An error occurred',
    ...(isDevelopment && { details: err.message }),
  };

  res.status(err.status || 500).json(errorResponse);
});

validateEnvironment();
```

