## 🔒 Security Review: app.js

### Executive Summary
The application has **moderate security concerns** that need to be addressed. While the basic structure is simple, there are several vulnerabilities and missing security best practices that could expose the application to attacks.

---

## 📋 Findings & OWASP Top 10 Analysis

### 1. **CRITICAL: Sensitive Data Exposure (OWASP A02:2021)**

**Issue:** The `.env.test` file contains hardcoded credentials and API keys.
- Database credentials
- AWS keys
- Anthropic API keys
- Stripe secret keys
- Logfire tokens

**Risk:** These secrets are committed to the repository and can be exposed through version control history or accidental uploads.

**Recommendation:**
```javascript
// ✅ SECURE: Use environment variables properly
require('dotenv').config({ path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env' });

// Verify required secrets are loaded
const requiredEnvVars = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'ANTHROPIC_API_KEY'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName]) {
    throw new Error(`Missing required environment variable: ${varName}`);
  }
});
```

**Actions:**
- ✅ Add `.env` and `.env.test` to `.gitignore`
- ✅ Use a secrets management tool (AWS Secrets Manager, HashiCorp Vault)
- ✅ Never commit real credentials—use dummy values for testing only
- ✅ Rotate all exposed secrets immediately

---

### 2. **HIGH: Missing Authentication & Authorization (OWASP A07:2021)**

**Issue:** All endpoints are publicly accessible without any authentication:

```javascript
// ❌ VULNERABLE: No auth required
app.get('/users', (req, res) => {
  res.json([...]); // Anyone can access sensitive user data
});
```

**Risk:** Unauthorized access to sensitive user information, data breach.

**Recommendation:**
```javascript
// ✅ SECURE: Implement authentication middleware
const jwt = require('jsonwebtoken');

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer token

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Apply auth to sensitive endpoints
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Health check can remain public
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

---

### 3. **HIGH: Missing Input Validation & Rate Limiting (OWASP A03:2021)**

**Issue:** No input validation on query parameters or rate limiting.

**Vulnerability:** Potential for DOS attacks, parameter pollution attacks.

**Recommendation:**
```javascript
// ✅ SECURE: Add rate limiting
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,  // Disable `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// ✅ SECURE: Input validation
const { query, validationResult } = require('express-validator');

app.get('/users',
  authenticateToken,
  query('id').optional().isInt().toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // ... process validated input
    res.json([...]);
  }
);
```

---

### 4. **MEDIUM: Missing Security Headers (OWASP A05:2021)**

**Issue:** Application doesn't set critical security headers.

**Recommendation:**
```javascript
// ✅ SECURE: Add security headers middleware
const helmet = require('helmet');

app.use(helmet()); // Sets multiple security headers

app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
  },
}));

app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true,
}));

app.disable('x-powered-by'); // Hide Express server signature
```

---

### 5. **MEDIUM: No HTTPS/TLS Enforcement (OWASP A02:2021)**

**Issue:** Application runs on plain HTTP without SSL/TLS.

**Recommendation:**
```javascript
// ✅ SECURE: Enforce HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}
```

---

### 6. **MEDIUM: Insufficient Logging & Monitoring (OWASP A09:2021)**

**Issue:** No security event logging or monitoring.

**Recommendation:**
```javascript
// ✅ SECURE: Add comprehensive logging
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Log authentication attempts
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    logger.warn('Authentication failed: missing token', {
      ip: req.ip,
      path: req.path,
      timestamp: new Date(),
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn('Authentication failed: invalid token', {
        ip: req.ip,
        user: user?.id,
        timestamp: new Date(),
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};
```

---

### 7. **MEDIUM: Missing CORS Configuration (OWASP A01:2021)**

**Issue:** No CORS policy defined; defaults to unrestricted.

**Recommendation:**
```javascript
// ✅ SECURE: Configure CORS properly
const cors = require('cors');

const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',');

app.use(cors({
  origin: allowedOrigins,
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
```

---

### 8. **MEDIUM: Missing Error Handling (OWASP A01:2021)**

**Issue:** No centralized error handling; server errors could leak sensitive information.

**Recommendation:**
```javascript
// ✅ SECURE: Centralized error handler
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    ip: req.ip,
  });

  // Don't leak detailed error messages in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;

  res.status(statusCode).json({ error: message });
});
```

---

### 9. **LOW: Missing Content-Type Validation**

**Issue:** No validation of request Content-Type header.

**Recommendation:**
```javascript
// ✅ SECURE: Validate content types
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: false }));

app.post('/data', authenticateToken, (req, res) => {
  // Automatically validated by express.json()
  if (!req.is('application/json')) {
    return res.status(400).json({ error: 'Content-Type must be application/json' });
  }
  // ... process request
});
```

