  }

  try {
    const user = jwt.verify(token, process.env.JWT_SECRET);
    req.user = user;
    next();
  } catch (err) {
    logger.warn({ message: 'Invalid token', error: err.message, requestId: req.id });
    res.status(403).json({ error: 'Invalid token' });
  }
}

// ============ ROUTES ============

