      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter based on role
    const response = users.map(u => 
      req.user.role === 'admin' 
        ? u 
        : { id: u.id, name: u.name }
    );

    logger.info({ message: 'Users fetched', requestId: req.id, userId: req.user.id });
    res.json(response);
  }
);

// ============ ERROR HANDLING ============
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    requestId: req.id,
    url: req.url,
    ip: req.ip
  });

  res.status(err.status || 500).json({
    error: 'Internal server error',
    requestId: req.id
  });
});

