**Vulnerability:** Could be exploited for cross-site request forgery or unintended access from other domains.

**Recommendation:**
```javascript
const cors = require('cors');

// Restrict CORS to specific domains
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true, // Allow cookies
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));
```

---

#### **6. ⚠️ NO ENVIRONMENT VARIABLE USAGE FOR SECRETS**
**Severity:** High

**Issue:** Hardcoded configuration and no secrets management.

**Vulnerability:** Credentials exposed in source code.

**Recommendation:**
```javascript
require('dotenv').config(); // Load from .env file

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is not defined');
}

if (NODE_ENV === 'production' && !process.env.SSL_CERT) {
  throw new Error('SSL_CERT required in production');
}
```

---

#### **7. ⚠️ MISSING ERROR HANDLING & LOGGING**
**Severity:** Medium

**Issue:** No centralized error handling or security logging.

**Vulnerability:** Errors may leak sensitive information; attacks go undetected.

**Recommendation:**
```javascript
const winston = require('winston');

// Configure logging
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
  });

  // Don't expose internal errors to clients
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
  });
});
```

---

#### **8. ⚠️ NO CONTENT SECURITY POLICY (CSP)**
**Severity:** Medium

**Issue:** Missing CSP headers to prevent XSS attacks.

**Recommendation:**
```javascript
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));
```

---

#### **9. ⚠️ NO DEPENDENCY ON SECURITY HEADERS**
**Severity:** Low-Medium

**Issue:** Missing X-Frame-Options, X-Content-Type-Options, etc.

**Recommendation:**
```javascript
const helmet = require('helmet');

app.use(helmet()); // Enables all Helmet protections by default

// Fine-tune specific headers
app.use(helmet.noSniff()); // X-Content-Type-Options
app.use(helmet.frameguard({ action: 'deny' })); // X-Frame-Options
app.use(helmet.hidePoweredBy()); // Remove X-Powered-By header
app.use(helmet.hsts({ maxAge: 31536000, includeSubDomains: true }));
```

---

### **OWASP TOP 10 MAPPING**

| OWASP Risk | Status | Issue |
|-----------|--------|-------|
| A01:2021 - Broken Access Control | ⚠️ | No authentication on `/users` endpoint |
| A02:2021 - Cryptographic Failures | ⚠️ | No HTTPS enforcement |
| A03:2021 - Injection | ⚠️ | No input validation |
| A04:2021 - Insecure Design | ⚠️ | Sensitive data exposed without controls |
| A05:2021 - Security Misconfiguration | ⚠️ | No security headers, missing middleware |
| A06:2021 - Vulnerable Components | ⚠️ | Check dependencies for vulnerabilities |
| A07:2021 - Identification & Auth Failures | ⚠️ | No authentication mechanism |
| A09:2021 - SSRF | ✓ | Not applicable (no external requests) |
| A10:2021 - CSTI | ⚠️ | No rate limiting |

---

### **COMPLETE HARDENED EXAMPLE**

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const jwt = require('jsonwebtoken');
const winston = require('winston');

const app = express();

// Logger setup
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Security middleware
app.use(helmet());
app.use(xss());
app.use(mongoSanitize());

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);

app.use(express.json());

// Auth middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Unauthorized access attempt to ${req.path} from ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token attempt from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    ip: req.ip,
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

---

### **RECOMMENDED PACKAGES**

Install these for enhanced security:

