# Security Review: app.js
**Date:** 2026-05-23  
**Severity Levels:** 🔴 Critical | 🟠 High | 🟡 Medium | 🟢 Low

---

## Executive Summary

This Express.js application has **significant security vulnerabilities** that should be addressed before production deployment. The application is missing critical security middleware, has improper authentication/authorization mechanisms, and lacks input validation and rate limiting. Multiple OWASP Top 10 vulnerabilities are present.

---

## Vulnerabilities Found

### 1. 🔴 CRITICAL: Missing Authentication & Authorization (OWASP A01:2021 - Broken Access Control)

**Issue:** The `/users` endpoint returns sensitive user data without any authentication or authorization checks.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risk:** Any unauthenticated user can access sensitive user information including email addresses.

**Recommendation:** Implement authentication middleware before exposing user data.

**Secure Implementation Example:**
```javascript
const jwt = require('jsonwebtoken');

// Authentication middleware
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing authentication token' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.userId = decoded.id;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Protected route with authorization
app.get('/users', authMiddleware, (req, res) => {
  // Only return users if authenticated
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. 🔴 CRITICAL: No Input Validation (OWASP A03:2021 - Injection)

**Issue:** No validation on any incoming request parameters. If parameters are added later, injection attacks are likely.

**Risk:** SQL Injection, NoSQL Injection, Command Injection, and XSS attacks are possible.

**Secure Implementation Example:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/search', 
  query('q').trim().isLength({ min: 1, max: 100 }).escape(),
  query('id').isInt({ min: 1 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { q, id } = req.query;
    // Safe to use q and id now
    res.json({ results: [] });
  }
);
```

---

### 3. 🟠 HIGH: Missing Security Headers (OWASP A05:2021 - Security Misconfiguration)

**Issue:** No security headers are configured, leaving the application vulnerable to multiple attacks.

**Risks:**
- **Missing CSP:** Vulnerable to XSS attacks
- **Missing X-Frame-Options:** Clickjacking attacks
- **Missing X-Content-Type-Options:** MIME-sniffing attacks
- **Missing Strict-Transport-Security:** Man-in-the-middle attacks

**Secure Implementation Example:**
```javascript
const helmet = require('helmet');
const express = require('express');
const app = express();

// Add security headers using helmet
app.use(helmet());

// Additional custom headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  next();
});

app.listen(3000);
```

---

### 4. 🟠 HIGH: Missing CORS Configuration (OWASP A05:2021 - Security Misconfiguration)

**Issue:** CORS is not explicitly configured, which could lead to unauthorized cross-origin requests.

**Risk:** Cross-origin request forgery and unauthorized data access from malicious websites.

**Secure Implementation Example:**
```javascript
const cors = require('cors');

// Whitelist specific origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://example.com'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));
```

---

### 5. 🟠 HIGH: No Rate Limiting (OWASP A04:2021 - Insecure Design)

**Issue:** No rate limiting on API endpoints, allowing brute force and DoS attacks.

**Risk:**
- Brute force attacks on authentication endpoints
- Denial of Service (DoS)
- Credential stuffing attacks

**Secure Implementation Example:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter limit for authentication
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

app.post('/login', authLimiter, (req, res) => {
  // Login logic
});
```

---

### 6. 🟠 HIGH: Sensitive Data Exposure (OWASP A02:2021 - Cryptographic Failures)

**Issue:** Directly exposing user emails without encryption or any data protection mechanism.

**Risk:** Breach of personally identifiable information (PII).

**Secure Implementation Example:**
```javascript
const crypto = require('crypto');

// Only return necessary, non-sensitive fields
app.get('/users', authMiddleware, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' }, // No email exposure
    { id: 2, name: 'Bob' },
  ]);
});

// If email is needed, encrypt it
app.get('/users/:id/contact', authMiddleware, (req, res) => {
  const email = 'alice@example.com';
  const encrypted = crypto.createCipher('aes-256-cbc', process.env.ENCRYPTION_KEY)
    .update(email, 'utf8', 'hex');

  res.json({ encrypted_email: encrypted });
});
```

---

### 7. 🟡 MEDIUM: Missing Error Handling (OWASP A05:2021 - Security Misconfiguration)

**Issue:** No global error handling, which could leak stack traces and sensitive information.

**Risk:** Information disclosure through error messages.

**Secure Implementation Example:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  console.error(err); // Log error for debugging

  // Don't expose stack trace to client
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});

// Handle 404s
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});
```

---

### 8. 🟡 MEDIUM: Missing Request Body Parsing Limits

**Issue:** No limits on request body size, allowing potential DoS attacks.

**Risk:** Memory exhaustion and DoS attacks.

**Secure Implementation Example:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 9. 🟡 MEDIUM: No HTTPS Enforcement

**Issue:** Application doesn't enforce HTTPS, especially critical for authentication.

**Risk:** Man-in-the-middle attacks, credential theft.

**Secure Implementation Example:**
```javascript
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.host}${req.originalUrl}`);
  }
  next();
});
```

---

### 10. 🟢 LOW: Missing Logging & Monitoring

**Issue:** No request logging or monitoring for security events.

**Risk:** Cannot detect or investigate security incidents.

**Secure Implementation Example:**
```javascript
const morgan = require('morgan');

app.use(morgan('combined')); // or use winston for structured logging

// Log suspicious activity
app.use((req, res, next) => {
  if (req.query.password || req.body?.password) {
    console.warn(`[SECURITY] Potential password in query/body from ${req.ip}`);
  }
  next();
});
```

---

## Complete Secure Implementation Example

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());
app.use(morgan('combined'));
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// HTTPS enforcement
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.host}${req.originalUrl}`);
  }
  next();
});

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP'
});
app.use(limiter);

// Authentication middleware
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing authentication token' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.userId = decoded.id;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Health check (public endpoint)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected endpoint with input validation
app.get('/users', 
  authMiddleware,
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Return only safe data (no emails)
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ]);
  }
);

// Global error handler
app.use((err, req, res, next) => {
  console.error(err);

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
});

module.exports = app;
```

