164	### 4. **Missing Security Headers (OWASP A05: Security Misconfiguration)**
165	
166	**Issue:** Application doesn't set critical HTTP security headers.
167	
168	**Risk Level:** HIGH
169	- No protection against XSS attacks
170	- No CSRF protection
171	- Missing Clickjacking protection
172	- No Content Security Policy
173	
174	**Recommended Fix:**
175	```javascript
176	const helmet = require('helmet');
177	const csrf = require('csurf');
178	const cookieParser = require('cookie-parser');
179	
180	// Apply security headers
181	app.use(helmet());
182	app.use(helmet.contentSecurityPolicy({
183	  directives: {
184	    defaultSrc: ["'self'"],
185	    styleSrc: ["'self'", "'unsafe-inline'"],
186	    scriptSrc: ["'self'"],
187	    imgSrc: ["'self'", 'data:', 'https:'],
188	  },
189	}));
190	
191	// CSRF protection
192	app.use(cookieParser());
193	app.use(csrf({ cookie: true }));
194	
195	// Additional headers
196	app.use((req, res, next) => {
197	  res.setHeader('X-Content-Type-Options', 'nosniff');
198	  res.setHeader('X-Frame-Options', 'DENY');
199	  res.setHeader('X-XSS-Protection', '1; mode=block');
200	  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
201	  next();
202	});
203	```
