### 7. **Security Logging and Monitoring** ⚠️ MEDIUM RISK

**Finding:** No logging, monitoring, or audit trail.

**Details:**
- No request logging
- No security event tracking
- No suspicious activity detection
- No audit logs for sensitive operations
- Sensitive information may be logged

**Recommendation:**
```javascript
const express = require('express');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');
const app = express();

// Create log directory if it doesn't exist
const logDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir);
}

// Request logging
const accessLogStream = fs.createWriteStream(
  path.join(logDir, 'access.log'),
  { flags: 'a' }
);

app.use(morgan('combined', { stream: accessLogStream }));

// Security event logger
const securityLogger = {
  log: (event, details) => {
    const timestamp = new Date().toISOString();
    const logEntry = `[${timestamp}] ${event}: ${JSON.stringify(details)}\n`;
    fs.appendFileSync(
      path.join(logDir, 'security.log'),
      logEntry
    );
  }
};

// Middleware to track failed authentication attempts
const trackFailedAttempts = (req, res, next) => {
  res.on('finish', () => {
    if (res.statusCode === 401 || res.statusCode === 403) {
      securityLogger.log('UNAUTHORIZED_ACCESS_ATTEMPT', {
        ip: req.ip,
        path: req.path,
        method: req.method,
        userAgent: req.get('user-agent')
      });
    }
  });
  next();
};

app.use(trackFailedAttempts);

// Track sensitive operations
app.post('/users', (req, res) => {
  // ... endpoint logic ...

  securityLogger.log('USER_CREATED', {
    ip: req.ip,
    user: req.body.email,
    timestamp: new Date().toISOString()
  });

  res.status(201).json({ success: true });
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

module.exports = app;
```

