### 10. **A10: Server-Side Request Forgery (SSRF)** ⚠️ MEDIUM

**Issue:** Potential for SSRF if external URLs are fetched
- No URL validation for external requests
- No allowlist for permitted domains

**Risk:** Unauthorized internal access, data exfiltration

**Recommendation:**
```javascript
const axios = require('axios');
const url = require('url');

// Whitelist of allowed domains
const ALLOWED_DOMAINS = ['api.trusted-service.com', 'data.example.com'];

// Safe external request function
const makeExternalRequest = async (targetUrl) => {
  try {
    const parsed = url.parse(targetUrl);

    // Validate URL
    if (!parsed.hostname) {
      throw new Error('Invalid URL');
    }

    // Check against whitelist
    if (!ALLOWED_DOMAINS.includes(parsed.hostname)) {
      throw new Error('Domain not allowed');
    }

    // Prevent internal IP access
    const internalIPs = ['127.0.0.1', 'localhost', '::1'];
    if (internalIPs.includes(parsed.hostname) || /^192\.168|^10\.|^172\.1[6-9]\.|^172\.2[0-9]\.|^172\.3[01]\./.test(parsed.hostname)) {
      throw new Error('Internal IP access not allowed');
    }

    const response = await axios.get(targetUrl, { timeout: 5000 });
    return response.data;
  } catch (error) {
    logger.error({ error: error.message });
    throw new Error('Failed to fetch external resource');
  }
};
```

