## Additional Security Recommendations

### Missing Security Headers
```javascript
const helmet = require('helmet');

app.use(helmet()); // Applies default security headers

// Or configure manually:
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'"], // Avoid unsafe-inline in production
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  }
}));

app.use(helmet.xssFilter());
app.use(helmet.noSniff());
app.use(helmet.referrerPolicy({ policy: 'strict-origin-when-cross-origin' }));
app.use(helmet.hsts({ maxAge: 31536000, includeSubDomains: true }));
```

### Error Handling - Avoid Information Disclosure
```javascript
// BAD - Exposes sensitive information
app.get('/data', (req, res) => {
  try {
    // ... code ...
  } catch (error) {
    res.status(500).json(error); // Exposes stack trace!
  }
});

// GOOD - Generic error response
app.get('/data', (req, res) => {
  try {
    // ... code ...
  } catch (error) {
    logger.error({ error: error.message }); // Log detailed error
    res.status(500).json({ error: 'Internal server error' }); // Generic response
  }
});

// Global error handler
app.use((error, req, res, next) => {
  logger.error(error);
  res.status(error.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : error.message
  });
});
```

### Input Validation - Prevent XSS
```javascript
const { body, validationResult } = require('express-validator');
const xss = require('xss');

app.post('/submit', [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be 1-100 characters')
    .escape(), // Escape HTML
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Valid email required')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const cleanData = {
    name: xss(req.body.name),
    email: xss(req.body.email)
  };

  // Process clean data
  res.json({ message: 'Data received', data: cleanData });
});
```

