  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Extract Bearer token

  if (!token) {
    logger.warn({
      event: 'authentication_missing',
      path: req.path,
      ip: req.ip
    });
    return res.status(401).json({ error: 'Access token required' });
