172	### 5. **A05: Broken Authentication** ⚠️ CRITICAL
173	
174	**Issue:** No authentication system implemented
175	- No password hashing
176	- No session management
177	- No multi-factor authentication
178	- No password policy enforcement
179	
180	**Risk:** Unauthorized access, account takeover
181	
182	**Recommendation:**
183	```javascript
184	const jwt = require('jsonwebtoken');
185	const bcrypt = require('bcrypt');
186	
187	// Login endpoint with proper authentication
188	app.post('/login', async (req, res) => {
189	  try {
190	    const { username, password } = req.body;
191	
192	    // Validate input
193	    if (!username || !password) {
194	      return res.status(400).json({ error: 'Username and password required' });
195	    }
196	
197	    // Find user (from database)
198	    const user = await db.findUser(username);
199	    if (!user) {
200	      return res.status(401).json({ error: 'Invalid credentials' });
201	    }
202	
203	    // Compare hashed passwords
204	    const validPassword = await bcrypt.compare(password, user.passwordHash);
205	    if (!validPassword) {
206	      return res.status(401).json({ error: 'Invalid credentials' });
207	    }
208	
209	    // Generate JWT token
210	    const token = jwt.sign(
211	      { id: user.id, username: user.username },
212	      process.env.JWT_SECRET,
213	      { expiresIn: '1h' }
214	    );
215	
216	    res.json({ token, expiresIn: 3600 });
217	  } catch (error) {
218	    console.error(error);
219	    res.status(500).json({ error: 'Server error' });
220	  }
221	});
222	
223	// Register endpoint with password hashing
224	app.post('/register', async (req, res) => {
225	  try {
226	    const { username, password } = req.body;
227	
228	    // Validate input
229	    if (!username || !password || password.length < 12) {
230	      return res.status(400).json({ 
231	        error: 'Invalid username or password (min 12 characters)' 
232	      });
233	    }
234	
235	    // Hash password
236	    const saltRounds = 10;
237	    const passwordHash = await bcrypt.hash(password, saltRounds);
238	
239	    // Store in database
240	    await db.createUser(username, passwordHash);
241	    res.status(201).json({ message: 'User created successfully' });
242	  } catch (error) {
243	    console.error(error);
244	    res.status(500).json({ error: 'Registration failed' });
245	  }
246	});
247	```
