474	## Additional Security Recommendations
475	
476	### Missing Security Headers
477	```javascript
478	const helmet = require('helmet');
479	
480	app.use(helmet()); // Applies default security headers
481	
482	// Or configure manually:
483	app.use(helmet.contentSecurityPolicy({
484	  directives: {
485	    defaultSrc: ["'self'"],
486	    scriptSrc: ["'self'", "'unsafe-inline'"], // Avoid unsafe-inline in production
487	    styleSrc: ["'self'", "'unsafe-inline'"],
488	    imgSrc: ["'self'", 'data:', 'https:'],
489	  }
490	}));
491	
492	app.use(helmet.xssFilter());
493	app.use(helmet.noSniff());
494	app.use(helmet.referrerPolicy({ policy: 'strict-origin-when-cross-origin' }));
495	app.use(helmet.hsts({ maxAge: 31536000, includeSubDomains: true }));
496	```
497	
498	### Error Handling - Avoid Information Disclosure
499	```javascript
500	// BAD - Exposes sensitive information
501	app.get('/data', (req, res) => {
502	  try {
503	    // ... code ...
504	  } catch (error) {
505	    res.status(500).json(error); // Exposes stack trace!
506	  }
507	});
508	
509	// GOOD - Generic error response
510	app.get('/data', (req, res) => {
511	  try {
512	    // ... code ...
513	  } catch (error) {
514	    logger.error({ error: error.message }); // Log detailed error
515	    res.status(500).json({ error: 'Internal server error' }); // Generic response
516	  }
517	});
518	
519	// Global error handler
520	app.use((error, req, res, next) => {
521	  logger.error(error);
522	  res.status(error.status || 500).json({
523	    error: process.env.NODE_ENV === 'production' 
524	      ? 'Internal server error' 
525	      : error.message
526	  });
527	});
528	```
529	
530	### Input Validation - Prevent XSS
531	```javascript
532	const { body, validationResult } = require('express-validator');
533	const xss = require('xss');
534	
535	app.post('/submit', [
536	  body('name')
537	    .trim()
538	    .isLength({ min: 1, max: 100 })
539	    .withMessage('Name must be 1-100 characters')
540	    .escape(), // Escape HTML
541	  body('email')
542	    .isEmail()
543	    .normalizeEmail()
544	    .withMessage('Valid email required')
545	], (req, res) => {
546	  const errors = validationResult(req);
547	  if (!errors.isEmpty()) {
548	    return res.status(400).json({ errors: errors.array() });
549	  }
550	
551	  const cleanData = {
552	    name: xss(req.body.name),
553	    email: xss(req.body.email)
554	  };
555	
556	  // Process clean data
557	  res.json({ message: 'Data received', data: cleanData });
558	});
559	```
