# For local: Use separate, machine-local .env (not tracked in git)
```

---

### 🔴 High Severity Issues

#### 2. **Missing Authentication & Authorization (A01:2021 – Broken Access Control)**
**Severity:** HIGH

**Problem:** The `/users` endpoint returns all user data without any authentication or authorization checks.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risk:**
- Unauthenticated users can access sensitive user data
- No rate limiting prevents enumeration attacks
- No authorization checks for user-level access control

**Recommendation:**
```javascript
const express = require('express');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const app = express();

// 1. Add authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Forbidden' });
    req.user = user;
    next();
  });
};

// 2. Add rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// 3. Protect the endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Only return users the authenticated user should see
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

#### 3. **Missing Security Headers (A05:2021 – Security Misconfiguration)**
**Severity:** HIGH

**Problem:** The application doesn't set important HTTP security headers.

**Risk:**
- Vulnerable to XSS attacks (no Content-Security-Policy)
- Clickjacking attacks possible (no X-Frame-Options)
- MIME type sniffing (no X-Content-Type-Options)

**Recommendation:**
```javascript
const helmet = require('helmet');
const app = express();

// Add security headers automatically
app.use(helmet());

// Or manually configure:
app.use((req, res, next) => {
  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Enable XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Content Security Policy
  res.setHeader('Content-Security-Policy', "default-src 'self'");

  // Strict Transport Security (HTTPS only)
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Referrer Policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  next();
});
```

