### **9. ⚠️ LOW: Hardcoded Data**

**Issue:** User data is hardcoded in the application. In production, this should come from a database.

**Recommendation:**
```javascript
// Use environment-based database connections
const mongoose = require('mongoose');

mongoose.connect(process.env.MONGODB_URI);

const userSchema = new mongoose.Schema({
  id: Number,
  name: String,
  email: String
});

const User = mongoose.model('User', userSchema);

app.get('/users', authenticateToken, async (req, res) => {
  try {
    const users = await User.find({}, '-_id id name email');
    res.json(users);
  } catch (err) {
    logger.error(err);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});
```

